def fwd(tokens, inject=None):
    B = tokens.shape[0]
    WQ=W['L0.W_Q'][0]; WK=W['L0.W_K'][0]; WV=W['L0.W_V'][0]; WO=W['L0.W_O'][0]
    x = W['W_E'][tokens] + W['W_pos']
    if inject and 'embed' in inject: x = inject['embed'].reshape(B,6,18)
    Q = x@WQ + W['L0.b_Q'][0]; K = x@WK + W['L0.b_K'][0]
    logits = Q@K.transpose(0,2,1)/np.sqrt(7)
    logits = logits - logits.max(-1,keepdims=True)
    P = np.exp(logits); P = P/P.sum(-1,keepdims=True)
    if inject and 'attn0.pattern' in inject: P = inject['attn0.pattern'].reshape(B,6,6)
    V = x@WV + W['L0.b_V'][0]
    ao = P@V
    ao = ao@WO + W['L0.b_O']
    if inject and 'attn0.out' in inject: ao = inject['attn0.out'].reshape(B,6,18)
    rm = x + ao
    if inject and 'resid0.mid' in inject: rm = inject['resid0.mid'].reshape(B,6,18)
    pre = rm@W['L0.W_in'] + W['L0.b_in']
    if inject and 'mlp0.pre' in inject: pre = inject['mlp0.pre'].reshape(B,6,16)
    post = np.maximum(pre,0)
    if inject and 'mlp0.post' in inject: post = inject['mlp0.post'].reshape(B,6,16)
    mo = post@W['L0.W_out'] + W['L0.b_out']
    if inject and 'mlp0.out' in inject: mo = inject['mlp0.out'].reshape(B,6,18)
    rp = rm + mo
    if inject and 'resid0.post' in inject: rp = inject['resid0.post'].reshape(B,6,18)
    out = rp[:,1:,:]@W['W_U']
    return dict(embed=x.reshape(B,108), pattern=P.reshape(B,36), attn0_out=ao.reshape(B,108),
                resid_mid=rm.reshape(B,108), pre=pre.reshape(B,96), post=post.reshape(B,96),
                mlp_out=mo.reshape(B,108), resid_post=rp.reshape(B,108), out=out.reshape(B,10))

