TOKS = np.array([1.,2.,3.,5.])
def ohcode(tt):  # tt [B,5] -> [B,5,4]
    return (tt[:,:,None]==TOKS[None,None,:]).astype(float)

def my_model(tokens, override=None):
    """tokens [B,6]. override: dict name->array replacing the iv value at that name."""
    B = tokens.shape[0]
    tt = tokens[:,1:6]
    oh = ohcode(tt)  # [B,5,4]
    def iv(name, val):
        if override and name in override:
            return override[name]
        return val
    tok = np.stack([iv("tok%d"%p, oh[:,p,:]) for p in range(5)],1)   # [B,5,4]
    a1 = iv("a1", tok[:,0,:])
    mid = np.stack([iv("mid0", np.concatenate([a1],-1))] + [iv("mid%d"%p, tok[:,p,:]) for p in range(1,5)],1)
    pre = np.stack([iv("pre0", mid[:,0,:])] + [iv("pre%d"%p, mid[:,p,:]) for p in range(1,5)],1)
    eq = (pre * pre[:,0:1,:]).sum(-1)     # [B,5]
    eqv = iv("eq", eq)
    return np.stack([1-eqv, eqv],-1).reshape(B,10)

def dec_of(out): return out.reshape(-1,5,2).argmax(-1)

