def site_vars(tokens, site, override=None):
    """returns dict name-> array for the variables at a site, computed by my_model's pipeline"""
    B=tokens.shape[0]
    tt=tokens[:,1:6]; oh=ohcode(tt)
    tok = oh
    a1 = tok[:,0,:]
    if site=='embed':
        return {"tok%d"%p: oh[:,p,:] for p in range(5)}
    if site=='attn0.out':
        return {"a1": a1}
    if site in ('resid0.mid','mlp0.pre'):
        mid = np.concatenate([a1[:,None,:], tok[:,1:,:]],1)
        if site=='resid0.mid':
            return {"mid0": mid[:,0,:], **{"mid%d"%p: mid[:,p,:] for p in range(1,5)}}
        return {"pre0": mid[:,0,:], **{"pre%d"%p: mid[:,p,:] for p in range(1,5)}}
    if site in ('mlp0.out','resid0.post'):
        eq = (tok*tok[:,0:1,:]).sum(-1)
        return {"eq": eq}
    return {}
